-- AccountServer database schema (PostgreSQL 18).
-- Ported from the SQL Server script: bit/tinyint -> smallint (never boolean, the
-- servers parse flags with integer conversion), datetime -> timestamp(3),
-- nvarchar(n) -> varchar(n), IDENTITY -> GENERATED BY DEFAULT AS IDENTITY.
-- All identifiers are lowercase and unquoted. Keep this file free of semicolons
-- inside strings and comments: the SQL contract harness splits it on semicolons.

create table account_charge (
  id integer not null,
  charge_flag integer,
  charge_begin_tick integer,
  charge_end_tick integer,
  saves integer,
  constraint pk_account_charge primary key (id)
);

create table account_details (
  acc_id integer not null,
  -- 1900-01-01 00:00:00: what SQL Server's ((1)/(1))/(1970) default (integer 0) meant for a datetime
  vipstatus timestamp(3) default '1900-01-01 00:00:00',
  squestion varchar(50) not null,
  answer varchar(50) not null,
  email varchar(100) not null,
  gender integer not null default 0,
  credit double precision not null default 0,
  truename varchar(50) not null,
  birthday timestamp(3) not null,
  contact varchar(50) not null,
  country varchar(50) not null,
  ipaddr varchar(50) not null,
  ip2country varchar(50) not null,
  activated integer not null default 0,
  actcode varchar(20),
  invtcode varchar(50),
  reference integer,
  create_time timestamp(3) not null,
  constraint pk_account_details primary key (acc_id)
);

create table account_invt (
  inv_id integer generated by default as identity,
  invt_code varchar(50) not null,
  assignto varchar(50),
  used integer not null,
  constraint pk_account_invt primary key (inv_id)
);

create table account_login (
  id integer generated by default as identity,
  name varchar(50),
  password varchar(255),
  salt varchar(255),
  sid integer not null default 0,
  login_status integer default 0,
  enable_login_tick bigint default 0,
  login_group varchar(50),
  last_login_time timestamp(3) default now(),
  last_logout_time timestamp(3) default now(),
  last_login_ip varchar(50),
  enable_login_time timestamp(3) default '2001-01-01 01:01:01',
  total_live_time bigint not null default 0,
  last_login_mac varchar(50),
  ban smallint,
  email varchar(50),
  constraint pk_account_login primary key (id),
  constraint ix_account_login unique (name)
);

create table account_pending (
  acc_id integer generated by default as identity,
  name varchar(50) not null,
  password varchar(50) not null,
  squestion varchar(100) not null,
  answer varchar(100) not null,
  email varchar(100) not null,
  gender integer not null default 0,
  truename varchar(100) not null,
  birthday timestamp(3) not null,
  contact varchar(50) not null,
  country varchar(50) not null,
  ipaddr varchar(50) not null,
  ip2country varchar(50) not null,
  actcode varchar(50),
  invtcode varchar(50),
  reference integer,
  create_time timestamp(3) not null,
  constraint pk_account_pending primary key (acc_id)
);

create table gamedbserverlist (
  server_section integer not null,
  server_ip varchar(128) not null,
  server_uid varchar(128) not null,
  server_pwd varchar(128) not null,
  server_db varchar(128) not null
);

create table lograndomaccount (
  accountname varchar(50) not null,
  adddate timestamp(3),
  expiredate timestamp(3),
  ip varchar(15),
  plainpassword varchar(32),
  constraint pk_lograndomaccount primary key (accountname)
);

create table safety (
  aid bigint generated by default as identity,
  allowip varchar(32) not null,
  constraint pk_safety primary key (aid)
);

create table server_group (
  sgid integer generated by default as identity,
  group_name varchar(50) not null,
  constraint pk_server_group primary key (sgid)
);

create table server_list (
  slid integer generated by default as identity,
  sgid integer not null,
  server_name varchar(50) not null,
  constraint pk_server_list2 primary key (slid)
);

create table traderecord (
  record_id varchar(50) not null,
  record_message integer not null,
  record_section integer not null,
  record_info varchar(4000) not null,
  record_time timestamp(3) not null,
  ret_info varchar(4000) not null,
  ret_time timestamp(3) not null,
  state integer not null
);

create table user_log (
  log_id integer generated by default as identity,
  user_id integer not null,
  user_name varchar(50) not null,
  login_time timestamp(3),
  logout_time timestamp(3),
  login_ip varchar(20)
);
